/**
 * Extracts the element type from an array type.
 * If the input is an array, returns the element type.
 * Otherwise, returns the type itself (for backward compatibility).
 *
 * @template T - The type to extract the element from
 *
 * @example
 * ```typescript
 * type StringArray = string[]
 * type Element = ExtractArrayElement<StringArray> // string
 *
 * type RecordArray = Record<'incident'>[]
 * type RecordElement = ExtractArrayElement<RecordArray> // Record<'incident'>
 * ```
 */
type ExtractArrayElement<T> = T extends (infer U)[] ? U : T;
/**
 * Creates a new ForEach step definition for the flow designer.
 * Automatically infers the item type from the array being iterated.
 *
 * **Type Safety**: Build-time validation enforces that only array types are accepted.
 * The type system helps with IntelliSense and item type inference.
 *
 * @template TArray - The type of the array being iterated (e.g., Record<'problem'>[])
 * @param _items - The array to iterate over. Should be wrapped with wfa.dataPill() using an array type.
 * @param _id - Configuration with $id and optional annotation
 * @param _body - Callback function that receives each item with proper typing
 *
 * @example
 * ```typescript
 * // ✓ Correct: array.object type
 * wfa.flowLogic.forEach(
 *     wfa.dataPill(problems.Records, 'array.object'),
 *     { $id: Now.ID['iterate_problems'] },
 *     (item) => { ... } // item is properly typed as Record<'problem'>
 * )
 *
 * // ✗ Build error: reference type is not an array
 * wfa.flowLogic.forEach(
 *     wfa.dataPill(result.record, 'reference'), // Build-time error!
 *     { $id: Now.ID['iterate'] },
 *     () => { ... }
 * )
 * ```
 */
export declare function ForEach<TArray>(_items: TArray | undefined, _id: Now.Internal.WithID<{
    annotation?: string;
}>, _body?: (item: ExtractArrayElement<TArray>) => void): {
    type: 'foreach';
};
export {};
